 pageHeading('Մասնաճյուղերի պահանջագրեր','Պահանջ, հաստատում, FEFO հավաքագրում և ստացման հաստատում');newButton('Նոր պահանջագիր','requests','requests');tableStart(['Պահանջագիր','Ամսաթիվ','Մասնաճյուղ','Հայցող','Ապրանքներ','Հրատապություն','Կարգավիճակ','Գործողություն']);$sql='SELECT r.*,b.name branch_name,u.name actor_name,(SELECT COUNT(*) FROM request_items i WHERE i.request_id=r.id) line_count FROM stock_requests r JOIN branches b ON b.id=r.branch_id JOIN users u ON u.id=r.requested_by';if(currentLocation())$sql.=' WHERE r.branch_id='.currentLocation();$sql.=' ORDER BY r.id DESC';$rows=db()->query($sql)->fetchAll();if(!$rows)trEmpty(8);foreach($rows as $r):?><tr><td><b><?=h($r['request_no'])?></b><small><?=h($r['reason'])?></small></td><td><?=h(date('d.m.Y',strtotime($r['created_at'])))?></td><td><?=h($r['branch_name'])?></td><td><?=h($r['actor_name'])?></td><td><?=h($r['line_count'])?> ապրանք</td><td><?=h(['urgent'=>'Շտապ','high'=>'Բարձր','normal'=>'Սովորական'][$r['urgency']]??$r['urgency'])?></td><td><?=pill($r['status'])?><?php if($r['status']==='rejected'):?><small><?=h($r['rejection_reason'])?></small><?php endif?></td><td class="actions-cell"><?php if(in_array($r['status'],['sent','review'],true)&&can('requests','approve')):?><button class="table-action" onclick="openModal('review-<?=$r['id']?>')">Դիտել / որոշել</button><?php elseif(in_array($r['status'],['approved','partially_approved'],true)&&can('receipts','edit')):?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action" name="action" value="request_ship">Հավաքագրել և ուղարկել</button></form><?php elseif($r['status']==='shipped'&&(can('requests','edit'))):?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action" name="action" value="request_receive">✓ Ստացա</button></form><?php else:?>—<?php endif?></td></tr><?php endforeach;tableEnd();
