<?php elseif($page==='movements'):
 pageHeading('Պահեստի շարժ','Մուտքեր, ելքեր, բաշխումներ և ուղղումներ՝ ըստ ամսաթվի');?><form class="filter-bar" method="get"><input type="hidden" name="page" value="movements"><label>Սկսած<input type="date" name="from" value="<?=h($_GET['from']??date('Y-m-01'))?>"></label><label>Մինչև<input type="date" name="to" value="<?=h($_GET['to']??date('Y-m-d'))?>"></label><label>Գործողություն<select name="type"><option value="">Բոլորը</option><?php foreach(['receipt'=>'Մուտք','branch_out'=>'Բաշխում','branch_in'=>'Մասնաճյուղի ստացում','consumption'=>'Օգտագործում','return_in'=>'Վերադարձ պահեստ','return_supplier'=>'Մատակարարին վերադարձ','branch_transfer'=>'Տեղափոխում','transfer_sent'=>'Ուղարկված տեղափոխում','inventory_adjustment'=>'Գույքագրման ուղղում'] as $k=>$v):?><option value="<?=h($k)?>" <?=($_GET['type']??'')===$k?'selected':''?>><?=h($v)?></option><?php endforeach?></select></label><button class="secondary-button">Կիրառել</button><a class="secondary-button" href="?page=movements&amp;export=csv">Ներբեռնել CSV</a></form><?php tableStart(['Ամսաթիվ','Փաստաթուղթ','Գործողություն','Ապրանք / LOT','Պահեստից','Պահեստ','Քանակ','Գին','Կատարող']);$where='WHERE DATE(m.happened_at)>=? AND DATE(m.happened_at)<=?';$params=[$_GET['from']??date('Y-m-01'),$_GET['to']??date('Y-m-d')];if(!empty($_GET['type'])){$where.=' AND m.type=?';$params[]=$_GET['type'];}$q=db()->prepare("SELECT m.*,p.code,p.name product_name,s.lot_no,b1.name from_name,b2.name to_name,u.name actor_name FROM movements m JOIN products p ON p.id=m.product_id LEFT JOIN stock_lots s ON s.id=m.lot_id LEFT JOIN branches b1 ON b1.id=m.from_location LEFT JOIN branches b2 ON b2.id=m.to_location JOIN users u ON u.id=m.actor_id $where ORDER BY m.happened_at DESC");$q->execute($params);$rows=$q->fetchAll();if(isset($_GET['export'])&&$_GET['export']==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="diagen-movements.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Ամսաթիվ','Փաստաթուղթ','Գործողություն','Կոդ','Ապրանք','LOT','Պահեստից','Պահեստ','Քանակ','Գին','Կատարող']);foreach($rows as $r)fputcsv($out,[$r['happened_at'],$r['reference'],$r['type'],$r['code'],$r['product_name'],$r['lot_no'],$r['from_name']??'Կենտրոնական',$r['to_name']??'',$r['qty'],$r['unit_cost'],$r['actor_name']]);exit;}if(!$rows)trEmpty(9);foreach($rows as $r):?><tr><td><?=h(date('d.m.Y H:i',strtotime($r['happened_at'])))?></td><td><?=h($r['reference']?:$r['movement_no'])?></td><td><?=h(['receipt'=>'Մուտք','branch_out'=>'Բաշխում','branch_in'=>'Ստացում','consumption'=>'Օգտագործում','return_in'=>'Վերադարձ պահեստ','return_supplier'=>'Մատակարարին վերադարձ','branch_transfer'=>'Տեղափոխում','transfer_sent'=>'Ուղարկված տեղափոխում','inventory_adjustment'=>'Գույքագրման ուղղում'][$r['type']]??$r['type'])?></td><td><b><?=h($r['code'])?></b><small><?=h($r['product_name'])?> · <?=h($r['lot_no'])?></small></td><td><?=h($r['from_name']??'—')?></td><td><?=h($r['to_name']??'—')?></td><td><?=num($r['qty'])?></td><td><?=num($r['unit_cost'])?> ֏</td><td><?=h($r['actor_name'])?></td></tr><?php endforeach;tableEnd();?>
<?php elseif($page==='inventory'):
 pageHeading('Գույքագրում','Ֆիքսեք հաշվառված մնացորդը, գրանցեք փաստացի քանակն ու հաստատեք տարբերությունները');if(can('inventory','create')):?><form class="filter-bar" method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="inventory_start"><input type="hidden" name="return_page" value="inventory"><label>Պահեստ<select name="location_id" <?=currentLocation()?'disabled':''?>><?=optionRows($branches,currentLocation())?></select><?php if(currentLocation()):?><input type="hidden" name="location_id" value="<?=currentLocation()?>"><?php endif?></label><label class="wide-label">Նշում<input name="note" placeholder="Գույքագրման հիմք"></label><button class="primary-button">＋ Սկսել գույքագրումը</button></form><?php endif?><?php tableStart(['Փաստաթուղթ','Պահեստ','Սկսվել է','Գրանցող','Կարգավիճակ','Տողեր','Գործողություն']);$rows=db()->query('SELECT i.*,b.name branch_name,u.name actor_name,(SELECT COUNT(*) FROM inventory_lines l WHERE l.session_id=i.id) line_count FROM inventory_sessions i LEFT JOIN branches b ON b.id=i.location_id JOIN users u ON u.id=i.started_by ORDER BY i.id DESC')->fetchAll();if(currentLocation())$rows=array_values(array_filter($rows,fn($r)=>(int)$r['location_id']===currentLocation()));if(!$rows)trEmpty(7);foreach($rows as $r):?><tr><td><b><?=h($r['inventory_no'])?></b></td><td><?=h($r['branch_name']??'Կենտրոնական պահեստ')?></td><td><?=h(date('d.m.Y H:i',strtotime($r['started_at'])))?></td><td><?=h($r['actor_name'])?></td><td><?=pill($r['status'])?></td><td><?=h($r['line_count'])?></td><td><?php if($r['status']==='open'):?><button class="table-action" onclick="openModal('count-<?=$r['id']?>')">Մուտքագրել գույքագրումը</button><?php else:?>Ակտը գրանցված է<?php endif?></td></tr><?php endforeach;tableEnd();foreach($rows as $r)if($r['status']==='open')renderInventoryModal($r);?>
<?php elseif($page==='expiry'):
 pageHeading('Ժամկետների վերահսկում','FEFO հերթականություն և խմբաքանակների պիտանելիության ծանուցումներ');tableStart(['Պահեստ','Ապրանք','LOT','Մնացորդ','Պիտանի է մինչև','Մնացել է','Վիճակ','Մատակարար']);$sql='SELECT s.*,p.code,p.name product_name,p.unit,b.name branch_name,su.name supplier_name,DATEDIFF(s.expires_on,CURDATE()) days_left FROM stock_lots s JOIN products p ON p.id=s.product_id LEFT JOIN branches b ON b.id=s.location_id LEFT JOIN suppliers su ON su.id=s.supplier_id WHERE s.qty>0 AND s.expires_on IS NOT NULL';if(currentLocation())$sql.=' AND s.location_id='.currentLocation();$sql.=' ORDER BY s.expires_on';$rows=db()->query($sql)->fetchAll();if(!$rows)trEmpty(8);foreach($rows as $r):$days=(int)$r['days_left'];?><tr><td><?=h($r['branch_name']??'Կենտրոնական պահեստ')?></td><td><b><?=h($r['product_name'])?></b><small><?=h($r['code'])?></small></td><td><?=h($r['lot_no'])?></td><td><?=num($r['qty'])?> <?=h($r['unit'])?></td><td><?=h(date('d.m.Y',strtotime($r['expires_on'])))?></td><td><?=$days<0?'Անցել է '.abs($days).' օր':$days.' օր'?></td><td><?=pill($days<0?'rejected':($days<=30?'pending':($days<=90?'review':'received')))?></td><td><?=h($r['supplier_name'])?></td></tr><?php endforeach;tableEnd();?>
<?php elseif($page==='returns'):
 pageHeading('Վերադարձներ','Մասնաճյուղից կենտրոնական պահեստ կամ կենտրոնականից մատակարար');newButton('Գրանցել վերադարձ','returns','returns');tableStart(['Փաստաթուղթ','Ամսաթիվ','Ուղղություն','Ապրանք / LOT','Քանակ','Պատճառ','Պատասխանատու']);$rows=db()->query('SELECT r.*,p.name product_name,s.lot_no,u.name actor_name,b.name branch_name,sup.name supplier_name FROM returns r JOIN products p ON p.id=r.product_id LEFT JOIN stock_lots s ON s.id=r.lot_id JOIN users u ON u.id=r.actor_id LEFT JOIN branches b ON b.id=r.from_location LEFT JOIN suppliers sup ON sup.id=r.supplier_id ORDER BY r.id DESC')->fetchAll();if(currentLocation())$rows=array_values(array_filter($rows,fn($r)=>(int)$r['from_location']===currentLocation()));if(!$rows)trEmpty(7);foreach($rows as $r):?><tr><td><b><?=h($r['return_no'])?></b></td><td><?=h(date('d.m.Y',strtotime($r['created_at'])))?></td><td><?=h($r['direction']==='branch_to_central'?'Մասնաճյուղ → Կենտրոն':'Կենտրոն → Մատակարար')?></td><td><?=h($r['product_name'])?><small><?=h($r['lot_no'])?></small></td><td><?=num($r['qty'])?></td><td><?=h($r['reason'])?></td><td><?=h($r['actor_name'])?></td></tr><?php endforeach;tableEnd();if(can('returns','create'))renderReturnModal($products,$branches,$suppliers,currentLocation());?>
<?php elseif($page==='transfers'):
 pageHeading('Մասնաճյուղերի տեղափոխումներ','Հարցում, հաստատում, ուղարկում և ստացող պահեստի ընդունում');newButton('Նոր տեղափոխման հարցում','transfers','transfers');tableStart(['Փաստաթուղթ','Սկսնակ պահեստ','Նպատակակետ','Ապրանք','Քանակ','Պատճառ','Կարգավիճակ','Գործողություն']);$rows=db()->query('SELECT t.*,b1.name from_name,b2.name to_name,p.name product_name FROM transfers t JOIN branches b1 ON b1.id=t.from_branch JOIN branches b2 ON b2.id=t.to_branch JOIN products p ON p.id=t.product_id ORDER BY t.id DESC')->fetchAll();if(currentLocation())$rows=array_values(array_filter($rows,fn($r)=>(int)$r['from_branch']===currentLocation()||(int)$r['to_branch']===currentLocation()));if(!$rows)trEmpty(8);foreach($rows as $r):?><tr><td><b><?=h($r['transfer_no'])?></b><small><?=h(date('d.m.Y',strtotime($r['created_at'])))?></small></td><td><?=h($r['from_name'])?></td><td><?=h($r['to_name'])?></td><td><?=h($r['product_name'])?></td><td><?=num($r['qty'])?></td><td><?=h($r['reason'])?></td><td><?=pill($r['status'])?></td><td><?php if($r['status']==='pending'&&can('transfers','approve')):?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="transfers"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action" name="action" value="transfer_approve">Հաստատել և ուղարկել</button></form><?php else:?>—<?php endif?></td></tr><?php endforeach;tableEnd();if(can('transfers','create'))renderTransferModal($products,$branches,currentLocation());$q=db()->prepare("SELECT t.*,b1.name from_name,b2.name to_name,p.name product_name FROM transfers t JOIN branches b1 ON b1.id=t.from_branch JOIN branches b2 ON b2.id=t.to_branch JOIN products p ON p.id=t.product_id WHERE t.status='shipped'". (currentLocation()?' AND t.to_branch='.currentLocation():'')." ORDER BY t.id DESC");$q->execute();$arrivals=$q->fetchAll();if($arrivals):?><article class="page-card arrival-card"><div class="card-heading"><div><h2>Ստացման սպասող ապրանքներ</h2><p>Ստացող մասնաճյուղը հաստատում է ընդունումը</p></div></div><?php foreach($arrivals as $r):?><div class="arrival-row"><div><b><?=h($r['product_name'])?> · <?=h($r['transfer_no'])?></b><small><?=h($r['from_name'])?> → <?=h($r['to_name'])?> · <?=num($r['qty'])?></small></div><?php if(can('transfers','edit')):?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="transfers"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="primary-button" name="action" value="transfer_accept">Հաստատել ստացումը</button></form><?php endif?></div><?php endforeach?></article><?php endif?>
<?php elseif($page==='reports'):
 pageHeading('Հաշվետվություններ','Պահեստային մնացորդի, ժամկետների և ապրանքների շարժի ամփոփում');?><div class="report-grid"><a class="page-card report-tile" href="?page=stock"><span class="metric-icon blue">▤</span><b>Ընդհանուր մնացորդ</b><small>Ըստ պահեստի, ապրանքի, խմբաքանակի և արժեքի</small></a><a class="page-card report-tile" href="?page=movements"><span class="metric-icon purple">⇄</span><b>Պահեստի շարժ</b><small>Ժամանակահատվածով ֆիլտրում և CSV արտահանում</small></a><a class="page-card report-tile" href="?page=expiry"><span class="metric-icon orange">◷</span><b>Ժամկետներ</b><small>Ժամկետանց և 180/90/60/30/7 օրվա ահազանգեր</small></a><a class="page-card report-tile" href="?page=requests"><span class="metric-icon green">⇧</span><b>Պահանջագրեր</b><small>Մասնաճյուղերի բաց, հաստատված և մերժված պահանջներ</small></a></div><div class="metric-grid report-metrics"><article class="metric-card"><div><strong><?=num($totalQty)?></strong><span>Պաշար՝ միավոր</span></div></article><article class="metric-card"><div><strong><?=num($totalValue)?> ֏</strong><span>Պաշարի արժեք</span></div></article><article class="metric-card"><div><strong><?=$lowCount?></strong><span>Նվազագույնից ցածր</span></div></article><article class="metric-card"><div><strong><?=$openRequests?></strong><span>Բաց պահանջագիր</span></div></article></div>
<?php elseif($page==='roles'):
 pageHeading('Դերեր և իրավունքներ','Կարգավորեք յուրաքանչյուր դերի հասանելիությունը բաժիններին ու գործողություններին');$roleId=(int)($_GET['role']??array_key_first($roles));$q=db()->prepare('SELECT * FROM roles WHERE id=?');$q->execute([$roleId]);$selectedRole=$q->fetch()?:['title'=>''];$q=db()->query('SELECT * FROM permissions ORDER BY module,code');$all=$q->fetchAll();$q=db()->prepare('SELECT p.code FROM role_permissions rp JOIN permissions p ON p.id=rp.permission_id WHERE rp.role_id=?');$q->execute([$roleId]);$granted=array_flip($q->fetchAll(PDO::FETCH_COLUMN));$grouped=[];foreach($all as $p)$grouped[$p['module']][]=$p;?><div class="groups-layout"><div class="page-card roles-list"><h2>Համակարգի դերերը</h2><?php foreach($roles as $rid=>$name):?><a class="role-link <?=$rid===$roleId?'active':''?>" href="?page=roles&amp;role=<?=$rid?>"><b><?=h($name)?></b><small><?=h($rid===$roleId?'Ընտրված է':'Դերի կարգավորում')?></small></a><?php endforeach?></div><form method="post" class="page-card permissions-card"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="permission_save"><input type="hidden" name="role_id" value="<?=$roleId?>"><input type="hidden" name="return_page" value="roles"><div class="card-heading"><div><h2><?=h($selectedRole['title'])?></h2><p>Փոփոխությունները կիրառվում են օգտատիրոջ հաջորդ մուտքից։</p></div><button class="primary-button">Պահպանել իրավունքները</button></div><?php foreach($grouped as $module=>$perms):?><div class="permission-module"><h3><?=h($modules[$module][0]??$module)?></h3><div class="permission-checks"><?php foreach($perms as $p):?><label class="check-label"><input type="checkbox" name="permissions[]" value="<?=h($p['code'])?>" <?=isset($granted[$p['code']])?'checked':''?>><span><?=h(explode(' — ',$p['title'])[1]??$p['title'])?></span></label><?php endforeach?></div></div><?php endforeach?></form></div>
