function optionRows(array $items,int|string $selected=''):string{$out='';foreach($items as $id=>$name)$out.='<option value="'.h($id).'" '.((string)$id===(string)$selected?'selected':'').'>'.h($name).'</option>';return $out;}
function productOptions(array $items):string{$out='<option value="">Ընտրել ապրանքը</option>';foreach($items as $p)$out.='<option value="'.$p['id'].'">'.h($p['code'].' · '.$p['name']).'</option>';return $out;}
function renderModal(string $id,string $title,string $kind,array $fields,?array $record=null):void{?><div id="<?=h($id)?>" class="modal-backdrop" hidden><form method="post" class="modal-card"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="kind" value="<?=h($kind)?>"><?php if($record):?><input type="hidden" name="id" value="<?=h($record['id'])?>"><?php endif?><input type="hidden" name="return_page" value="<?=h($kind==='supplier'?'suppliers':'branches')?>"><div class="modal-head"><div><h2><?=h($title)?></h2><p>Դաշտերը պահպանվում են միասնական տեղեկատուում</p></div><button class="icon-button" type="button" onclick="closeModal('<?=h($id)?>')">×</button></div><div class="form-grid"><?php foreach($fields as $label=>$field):?><label><?=h($label)?><input name="<?=h($field)?>" value="<?=h($record[$field]??'')?>" <?=in_array($field,['name','code'],true)?'required':''?> type="<?=in_array($field,['email'],true)?'email':(in_array($field,['delivery_days'],true)?'number':'text')?>"></label><?php endforeach?><label class="check-label"><input type="checkbox" name="active" <?=!$record||!empty($record['active'])?'checked':''?>> Գործուն մատակարար / մասնաճյուղ</label></div><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('<?=h($id)?>')">Չեղարկել</button><button class="primary-button">Պահպանել</button></div></form></div><?php }
