function renderConsumeModal(array $products,array $branches):void{?><div id="consume-modal" class="modal-backdrop" hidden><form method="post" class="modal-card"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="consume"><input type="hidden" name="return_page" value="stock"><div class="modal-head"><div><h2>Գրանցել ներքին օգտագործումը</h2><p>Ապրանքը դուրս է գրվում ամենավաղ պիտանելիությամբ LOT-ից</p></div><button class="icon-button" type="button" onclick="closeModal('consume-modal')">×</button></div><div class="form-grid"><label>Պահեստ<select name="location_id" <?=currentLocation()?'disabled':''?>><?=optionRows($branches,currentLocation())?></select><?php if(currentLocation()):?><input type="hidden" name="location_id" value="<?=currentLocation()?>"><?php endif?></label><label>Ապրանք<select name="product_id" required><?=productOptions($products)?></select></label><label>Ելքի քանակ<input type="number" min="0.001" step="0.001" name="qty" required></label></div><div class="modal-actions"><button class="secondary-button" type="button" onclick="closeModal('consume-modal')">Չեղարկել</button><button class="primary-button">Գրանցել ելքը</button></div></form></div><?php }
function renderRequestModal(array $products,array $branches,int $branch):void{?><div id="requests-modal" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="request_create"><input type="hidden" name="return_page" value="requests"><div class="modal-head"><div><h2>Նոր մասնաճյուղային պահանջագիր</h2><p>Ընթացիկ մնացորդը և առաջարկվող քանակը երևում են ընտրված ապրանքի մոտ</p></div><button class="icon-button" type="button" onclick="closeModal('requests-modal')">×</button></div><div class="form-grid"><label>Մասնաճյուղ<select name="branch_id" <?=currentLocation()?'disabled':''?> required><?=optionRows($branches,$branch)?></select><?php if(currentLocation()):?><input type="hidden" name="branch_id" value="<?=$branch?>"><?php endif?></label><label>Հրատապություն<select name="urgency"><option value="normal">Սովորական</option><option value="high">Բարձր</option><option value="urgent">Շտապ</option></select></label><label class="span-2">Հիմնավորում<textarea name="reason" placeholder="Պահանջի նպատակը"></textarea></label></div><div id="request-lines"><div class="request-line"><label>Ապրանք<select name="items[0][product_id]" required><option value="">Ընտրել ապրանքը</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=h($p['code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Պահանջվող քանակ<input name="items[0][qty]" type="number" min="0.001" step="0.001" required></label><label>Մեկնաբանություն<input name="items[0][note]"></label></div></div><button type="button" class="text-link" onclick="addRequestLine()">＋ Ավելացնել ապրանք</button><div class="modal-actions"><button class="secondary-button" type="button" onclick="closeModal('requests-modal')">Չեղարկել</button><button class="primary-button">Ուղարկել պահանջագիրը</button></div></form></div><?php }
function renderReviewModal(array $r,array $products):void{$q=db()->prepare('SELECT i.*,p.name,p.code,p.unit,(SELECT COALESCE(SUM(qty),0) FROM stock_lots s WHERE s.product_id=p.id AND s.location_id=0) central_qty,(SELECT COALESCE(SUM(qty),0) FROM stock_lots s WHERE s.product_id=p.id AND s.location_id=?) branch_qty FROM request_items i JOIN products p ON p.id=i.product_id WHERE i.request_id=?');$q->execute([$r['branch_id'],$r['id']]);$items=$q->fetchAll();?><div id="review-<?=$r['id']?>" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="request_review"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="modal-head"><div><h2>Ստուգել <?=h($r['request_no'])?></h2><p><?=h($r['branch_name']??'Մասնաճյուղ')?> · <?=h($r['reason'])?></p></div><button class="icon-button" type="button" onclick="closeModal('review-<?=$r['id']?>')">×</button></div><?php foreach($items as $it):?><div class="review-line"><div><b><?=h($it['code'].' · '.$it['name'])?></b><small>Մասնաճյուղում՝ <?=num($it['branch_qty'])?> <?=$it['unit']?> · Կենտրոնում՝ <?=num($it['central_qty'])?></small></div><label>Պահանջել է <?=num($it['requested_qty'])?><input type="number" name="approved[<?=$it['id']?>]" min="0" max="<?=min($it['requested_qty'],$it['central_qty'])?>" step="0.001" value="<?=min($it['requested_qty'],$it['central_qty'])?>"></label></div><?php endforeach?><label>Մերժման պատճառ (մերժելիս պարտադիր)<textarea name="rejection_reason"></textarea></label><div class="modal-actions"><button class="danger-button" name="decision" value="reject">Մերժել</button><button class="primary-button" name="decision" value="approve">Հաստատել քանակները</button></div></form></div><?php }
function renderInventoryModal(array $r):void{$q=db()->prepare('SELECT il.*,p.name,p.code,p.unit,s.lot_no FROM inventory_lines il JOIN products p ON p.id=il.product_id LEFT JOIN stock_lots s ON s.id=il.lot_id WHERE il.session_id=? ORDER BY p.name');$q->execute([$r['id']]);$lines=$q->fetchAll();?><div id="count-<?=$r['id']?>" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="inventory_count"><input type="hidden" name="return_page" value="inventory"><input type="hidden" name="session_id" value="<?=$r['id']?>"><div class="modal-head"><div><h2><?=h($r['inventory_no'])?> · Փաստացի հաշվարկ</h2><p>Հաշվարկված մնացորդը ֆիքսվել է գույքագրումն սկսելիս</p></div><button class="icon-button" type="button" onclick="closeModal('count-<?=$r['id']?>')">×</button></div><div class="count-list"><?php foreach($lines as $line):?><div class="count-line"><div><b><?=h($line['name'])?></b><small><?=h($line['code'])?> · LOT <?=h($line['lot_no'])?> · Հաշվառված՝ <?=num($line['expected_qty'])?> <?=h($line['unit'])?></small></div><label>Փաստացի քանակ<input name="counted[<?=$line['id']?>]" type="number" min="0" step="0.001" value="<?=h($line['counted_qty']??'')?>" required></label><label>Տարբերության պատճառ<input name="reason[<?=$line['id']?>]" value="<?=h($line['difference_reason'])?>" placeholder="Լրացնել միայն տարբերության դեպքում"></label></div><?php endforeach?></div><div class="modal-actions"><button class="secondary-button">Պահպանել քանակները</button><button class="primary-button" formaction="?page=inventory" name="action" value="inventory_close" onclick="return confirm('Փակե՞լ գույքագրումը և կիրառել տարբերությունները։')">Փակել գույքագրումը</button></div></form></div><?php }
function renderReturnModal(array $products,array $branches,array $suppliers,int $branch):void{?><div id="returns-modal" class="modal-backdrop" hidden><form method="post" class="modal-card"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="return_create"><input type="hidden" name="return_page" value="returns"><div class="modal-head"><div><h2>Գրանցել ապրանքի վերադարձ</h2><p>Մնացորդը կհաշվարկվի առկա FEFO խմբաքանակներից</p></div><button type="button" class="icon-button" onclick="closeModal('returns-modal')">×</button></div><div class="form-grid"><label>Վերադարձի տեսակ<select name="direction"><option value="branch_to_central">Մասնաճյուղ → Կենտրոն</option><option value="central_to_supplier">Կենտրոն → Մատակարար</option></select></label><label>Մասնաճյուղ<select name="from_location" <?=currentLocation()?'disabled':''?>><?=optionRows($branches,$branch)?></select><?php if(currentLocation()):?><input type="hidden" name="from_location" value="<?=$branch?>"><?php endif?></label><label>Մատակարար (մատակարարին վերադարձի դեպքում)<select name="supplier_id"><option value="">Ընտրել</option><?=optionRows($suppliers)?></select></label><label>Ապրանք<select name="product_id" required><?=productOptions($products)?></select></label><label>Քանակ<input type="number" name="qty" min="0.001" step="0.001" required></label><label class="span-2">Պատճառ<textarea name="reason" required></textarea></label></div><div class="modal-actions"><button class="secondary-button" type="button" onclick="closeModal('returns-modal')">Չեղարկել</button><button class="primary-button">Գրանցել վերադարձը</button></div></form></div><?php }
function renderTransferModal(array $products,array $branches,int $branch):void{?><div id="transfers-modal" class="modal-backdrop" hidden><form method="post" class="modal-card"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="transfer_create"><input type="hidden" name="return_page" value="transfers"><div class="modal-head"><div><h2>Նոր տեղափոխման հարցում</h2><p>Հաստատումից հետո երկու մասնաճյուղի մնացորդները կփոխվեն</p></div><button type="button" class="icon-button" onclick="closeModal('transfers-modal')">×</button></div><div class="form-grid"><label>Ուղարկող պահեստ<select name="from_branch" <?=currentLocation()?'disabled':''?>><?=optionRows($branches,$branch)?></select><?php if(currentLocation()):?><input type="hidden" name="from_branch" value="<?=$branch?>"><?php endif?></label><label>Ստացող պահեստ<select name="to_branch" required><?=optionRows($branches)?></select></label><label>Ապրանք<select name="product_id" required><?=productOptions($products)?></select></label><label>Քանակ<input name="qty" type="number" min="0.001" step="0.001" required></label><label class="span-2">Պատճառ<textarea name="reason" required></textarea></label></div><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('transfers-modal')">Չեղարկել</button><button class="primary-button">Ուղարկել հաստատման</button></div></form></div><?php }
